SELECT COUNT(*) AS "count_result" FROM triples t0, triples t1, triples t2, triples t3 WHERE t0.p = 'http://xmlns.com/foaf/age' AND t0.o = struct_pack(kind := 0::UTINYINT, value := 'http://db.uwaterloo.ca/~galuc/wsdbm/AgeGroup5', datatype := NULL::VARCHAR, lang := NULL::VARCHAR) AND struct_pack(kind := 0::UTINYINT, value := t1.s, datatype := NULL::VARCHAR, lang := NULL::VARCHAR) = struct_pack(kind := 0::UTINYINT, value := t0.s, datatype := NULL::VARCHAR, lang := NULL::VARCHAR) AND t1.p = 'http://xmlns.com/foaf/familyName' AND t2.p = 'http://purl.org/ontology/mo/artist' AND t2.o = struct_pack(kind := 0::UTINYINT, value := t0.s, datatype := NULL::VARCHAR, lang := NULL::VARCHAR) AND struct_pack(kind := 0::UTINYINT, value := t3.s, datatype := NULL::VARCHAR, lang := NULL::VARCHAR) = struct_pack(kind := 0::UTINYINT, value := t0.s, datatype := NULL::VARCHAR, lang := NULL::VARCHAR) AND t3.p = 'http://schema.org/nationality' AND t3.o = struct_pack(kind := 0::UTINYINT, value := 'http://db.uwaterloo.ca/~galuc/wsdbm/Country1', datatype := NULL::VARCHAR, lang := NULL::VARCHAR)